const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Approximate geometry for Lac Rouge, Quebec (a small lake near Fermont is often referred to as Lac Rouge)
  // This is a placeholder polygon; exact lake boundaries would require a precise shapefile or manual digitization.
  const geometry = ee.Geometry.Polygon(
    [[[-66.83, 52.41],
      [-66.79, 52.41],
      [-66.79, 52.38],
      [-66.83, 52.38],
      [-66.83, 52.41]]]);

  const date1_start = '2024-06-01';
  const date1_end = '2024-07-01'; // Centered around June 21, 2024
  const date2_start = '2025-06-01';
  const date2_end = '2025-07-01'; // Centered around June 15, 2025

  const cloud_threshold = 20; // Max percentage of cloud cover allowed in an image
  const scale = 10; // Sentinel-2 resolution for water analysis

  // Function to mask clouds in Sentinel-2 images
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select(['B8', 'B3', 'B11']) // NIR, Green, SWIR1
      .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDWI and create a water mask
  function getWaterMask(image) {
    // NDWI = (Green - NIR) / (Green + NIR) for Sentinel-2
    // B3 is Green, B8 is NIR
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    // A common threshold for water is NDWI > 0
    const waterMask = ndwi.gt(0).rename('water');
    return image.addBands(ndwi).addBands(waterMask);
  }

  // Function to get and process image collection for a given period
  async function processCollection(startDate, endDate, periodName) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', cloud_threshold));

    const size = await collection.size().getInfo();
    if (size === 0) {
      console.log(`${periodName} Images: 0`);
      return null;
    }

    // Apply cloud mask and select relevant bands (NIR, Green, SWIR1 for NDWI/MNDWI)
    collection = collection.map(maskS2clouds);

    // Get the median composite
    const composite = collection.median();
    if (composite === null) {
        console.log(`${periodName} composite is null.`);
        return null;
    }

    // Calculate NDWI and water mask
    const waterImage = getWaterMask(composite);

    // Calculate water pixel count
    const waterAreaReducer = ee.Reducer.sum().unweighted();
    const waterCount = await waterImage.select('water')
      .reduceRegion({
        reducer: waterAreaReducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get('water').getInfo();

    // Calculate total area in km^2 by multiplying pixel count by pixel area in km^2
    const pixelAreaSqM = ee.Image.pixelArea().reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();
    const pixelAreaM2 = pixelAreaSqM ? pixelAreaSqM['area'] : 0;
    const totalImageAreaKm2 = pixelAreaM2 / 1e6;

    const waterAreaM2 = waterCount * (scale * scale);
    const waterAreaKm2 = waterAreaM2 / 1e6;

    const cloud_pixels_reducer = ee.Reducer.count();
    const validPixels = await composite.select('B8').reduceRegion({
        reducer: cloud_pixels_reducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    }).get('B8').getInfo();

    console.log(`${periodName} Images: ${size} (Valid Pixels: ${validPixels || 0})`);
    if (validPixels === 0) {
        return { area: 0, validPixels: 0 };
    }

    return { area: waterAreaKm2, validPixels: validPixels };
  }

  // 2. Data Acquisition & Check
  console.log('--- Analyzing Lac Rouge Area ---');
  const result1 = await processCollection(date1_start, date1_end, '2024 (June 21)');
  const result2 = await processCollection(date2_start, date2_end, '2025 (June 15)');

  if (result1 === null || result2 === null) {
    console.log("C1");
    return;
  }

  if (result1.validPixels === 0 || result2.validPixels === 0) {
    console.log("C2");
    return;
  }

  const area1 = result1.area;
  const area2 = result2.area;

  if (area1 === null || area2 === null || isNaN(area1) || isNaN(area2)) {
    console.log("C3");
    return;
  }

  // 3. Calculation & 4. Validation & Final Answer
  console.log(`Lac Rouge area 2024: ${area1.toFixed(3)} km²`);
  console.log(`Lac Rouge area 2025: ${area2.toFixed(3)} km²`);

  if (area1 === 0 && area2 === 0) {
    console.log("C3"); // Both areas are zero, implying no water, or calculation issue.
    return;
  }

  if (area1 === 0) { // If it was 0 in 2024, it can't shrink by >90% meaningfully.
    console.log("C3"); // Cannot calculate shrinkage percentage from zero initial area.
    return;
  }

  const shrinkage = ((area1 - area2) / area1) * 100;
  console.log(`Shrinkage: ${shrinkage.toFixed(2)}%`);

  if (shrinkage > 90) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
